3	 *
4	 *   public/video/intro.mp4   (or .webm)  — opening: the official cartoon girl loads the towel with Benny,
5	 *                                          closes the washer door and walks away (replaces real-time 01)
6	 *   public/video/ending.mp4  (or .webm)  — optional ending, played before the real-time 11 victory frame
7	 *
8	 * If a file is missing the real-time 3D cinematic plays instead, so the game always works without them.
9	 * Videos are always muted (silent) and inline. Gameplay 03–10 is never replaced: the 3D scene keeps
10	 * running underneath (held on the matching moment) and is revealed by a cross-fade when the video ends.
11	 *
12	 * URL overrides for testing: ?introVideo=<same-origin path>, ?endingVideo=<path>, ?video=0 (disable).
13	 * QA captures (?qa) never play videos, so screenshots stay deterministic.
14	 */
15	export type CinematicName = 'intro' | 'ending';
16	export type CinematicResult = 'ended' | 'skipped' | 'failed';
17	
18	/**
19	 * Edge-to-edge fit (no black bars, no stretching) for any clip on any phone:
20	 *  - 'cover' when cropping keeps at least COVER_MIN_KEEP of the clip (e.g. a 9:16 clip on a 20:9 phone
21	 *    keeps 80% of its width). The crop is centred on `focus` (CSS object-position).
22	 *  - otherwise 'fill': the whole clip is shown (contain) over a soft, blurred, zoomed copy of the SAME
23	 *    frames that fills the rest of the screen (e.g. a 16:9 Flow clip on a portrait phone). The fill is a
24	 *    tiny canvas updated per video frame, so there is only one video decode.
25	 */
26	export const COVER_MIN_KEEP = 0.78;
27	export type VideoFit = 'cover' | 'fill';
28	export function chooseVideoFit(videoW: number, videoH: number, screenW: number, screenH: number): { fit: VideoFit; keep: number } {
29	  if (!(videoW > 0 && videoH > 0 && screenW > 0 && screenH > 0)) return { fit: 'cover', keep: 1 };
30	  const va = videoW / videoH, sa = screenW / screenH;
31	  const keep = Math.min(va / sa, sa / va); // fraction of the clip still visible after a cover crop
32	  return { fit: keep >= COVER_MIN_KEEP ? 'cover' : 'fill', keep };
33	}
