35	function canLoad(url: string, timeoutMs = 4000): Promise<boolean> {
36	  return new Promise((resolve) => {
37	    const v = document.createElement('video');
38	    let done = false;
39	    const finish = (ok: boolean) => {
40	      if (done) return;
41	      done = true;
42	      v.removeAttribute('src');
43	      v.load();
44	      resolve(ok);
45	    };
46	    v.preload = 'metadata';
47	    v.muted = true;
48	    v.onloadedmetadata = () => finish(v.duration > 0);
49	    v.onerror = () => finish(false);
50	    setTimeout(() => finish(false), timeoutMs);
51	    v.src = url;
52	  });
53	}
54	
55	/** Returns the URL of the cinematic if one is installed (and allowed), otherwise null. */
56	export async function findCinematic(name: CinematicName): Promise<string | null> {
57	  const q = new URLSearchParams(location.search);
58	  if (q.has('qa') || q.get('video') === '0') return null;
59	  const override = q.get(`${name}Video`);
60	  const candidates = override && override.startsWith('/') && !override.startsWith('//')
61	    ? [override]
62	    : [`./video/${name}.mp4`, `./video/${name}.webm`];
63	  for (const url of candidates) {
64	    if (await canLoad(url)) return url;
65	  }
66	  return null;
67	}
68	
69	/**
70	 * Plays a cinematic full-screen over the game. `onEnding` fires as the cross-fade starts (release the
71	 * held 3D scene there), and the promise resolves once the overlay is gone. Tap to skip after 0.6 s.
72	 */
73	export function playCinematic(
74	  url: string,
75	  opts: { onEnding?: (r: CinematicResult) => void; fadeMs?: number; focus?: string } = {},
76	): Promise<CinematicResult> {
77	  const fadeMs = opts.fadeMs ?? 700;
78	  const focus = opts.focus ?? new URLSearchParams(location.search).get('videoFocus') ?? '50% 50%';
79	  return new Promise((resolve) => {
80	    const wrap = document.createElement('div');
81	    wrap.setAttribute('data-cinematic', url);
82	    wrap.style.cssText =
83	      'position:fixed;inset:0;z-index:50;background:#2a0b46;display:flex;align-items:center;justify-content:center;' +
84	      `transition:opacity ${fadeMs}ms ease;opacity:1;touch-action:none;`;
85	    const v = document.createElement('video');
86	    v.src = url;
87	    v.muted = true;
88	    v.defaultMuted = true;
89	    v.playsInline = true;
90	    v.setAttribute('playsinline', '');
91	    v.setAttribute('webkit-playsinline', '');
92	    v.preload = 'auto';
93	    v.style.cssText = `position:relative;width:100%;height:100%;object-fit:cover;object-position:${focus};`;
94	    // blurred fill behind a 'fill'-fitted clip (hidden while the clip is cover-fitted)
95	    const fillCv = document.createElement('canvas');
96	    fillCv.width = 48; fillCv.height = 48;
97	    fillCv.setAttribute('data-cinematic-fill', '');
98	    fillCv.style.cssText = 'position:absolute;inset:-6%;width:112%;height:112%;filter:blur(18px) saturate(1.25) brightness(0.8);display:none;';
99	    const fillCtx = fillCv.getContext('2d');
100	    let fitMode: VideoFit = 'cover';
101	    const applyFit = () => {
102	      const r = chooseVideoFit(v.videoWidth, v.videoHeight, wrap.clientWidth || innerWidth, wrap.clientHeight || innerHeight);
103	      fitMode = r.fit;
104	      v.style.objectFit = r.fit === 'cover' ? 'cover' : 'contain';
105	      fillCv.style.display = r.fit === 'fill' ? 'block' : 'none';
106	      wrap.dataset.fit = r.fit;
107	      wrap.dataset.keep = r.keep.toFixed(3);
108	    };
109	    const paintFill = () => {
110	      if (fitMode !== 'fill' || !fillCtx || v.readyState < 2) return;
111	      // cover-crop the frame into the small fill canvas
112	      const s = Math.max(fillCv.width / v.videoWidth, fillCv.height / v.videoHeight);
113	      const w = v.videoWidth * s, h = v.videoHeight * s;
114	      fillCtx.drawImage(v, (fillCv.width - w) / 2, (fillCv.height - h) / 2, w, h);
115	    };
116	    type RVFC = (cb: () => void) => number;
117	    const rvfc = (v as unknown as { requestVideoFrameCallback?: RVFC }).requestVideoFrameCallback?.bind(v);
118	    const pump = () => { if (finished) return; paintFill(); if (rvfc) rvfc(pump); else requestAnimationFrame(pump); };
119	    window.addEventListener('resize', applyFit);
120	    const hint = document.createElement('div');
121	    hint.textContent = 'Tap to skip';
122	    hint.style.cssText =
123	      'position:absolute;bottom:calc(24px + env(safe-area-inset-bottom));left:0;right:0;text-align:center;' +
124	      'font:600 15px "Baloo 2",system-ui,sans-serif;color:#fff;opacity:0;transition:opacity .4s;' +
125	      'text-shadow:0 1px 4px rgba(0,0,0,.6);pointer-events:none;';
126	    wrap.append(fillCv, v, hint);
127	    document.body.append(wrap);
128	
129	    let finished = false;
130	    const t0 = performance.now();
131	    const finish = (r: CinematicResult) => {
132	      if (finished) return;
133	      finished = true;
134	      opts.onEnding?.(r);
135	      wrap.style.opacity = '0';
136	      window.removeEventListener('resize', applyFit);
137	      setTimeout(() => { v.pause(); wrap.remove(); resolve(r); }, fadeMs + 50);
138	    };
139	    // edge-to-edge: crop when little is lost, otherwise whole clip over a blurred fill (never plain bars)
140	    v.onloadedmetadata = () => { applyFit(); pump(); };
141	    v.onended = () => finish('ended');
142	    v.onerror = () => finish('failed');
143	    setTimeout(() => { hint.style.opacity = '0.85'; }, 600);
144	    let waitingForTap = false;
145	    wrap.addEventListener('pointerdown', () => {
146	      if (waitingForTap) {
147	        waitingForTap = false;
148	        hint.textContent = 'Tap to skip';
149	        v.play().catch(() => finish('failed'));
150	        return;
151	      }
152	      if (performance.now() - t0 > 600) finish('skipped');
153	    });
154	    v.play().catch(() => {
155	      // autoplay refused (rare for muted inline video): the first tap starts playback instead of skipping
156	      waitingForTap = true;
157	      hint.textContent = 'Tap to play';
158	      hint.style.opacity = '0.85';
159	    });
160	  });
161	}
