64	const HEART = `<svg class="icon" viewBox="0 0 64 64"><defs><radialGradient id="hg" cx="35%" cy="30%" r="75%"><stop offset="0" stop-color="#ffd0e4"/><stop offset="0.45" stop-color="#ff5f9e"/><stop offset="1" stop-color="#e01e6a"/></radialGradient></defs><path d="M32 57 C10 41 4 30 4 20 C4 11 11 5 19 5 C25 5 29 8 32 13 C35 8 39 5 45 5 C53 5 60 11 60 20 C60 30 54 41 32 57Z" fill="url(#hg)" stroke="#fff" stroke-opacity=".5" stroke-width="2"/><ellipse cx="20" cy="17" rx="7" ry="4.5" fill="#fff" opacity=".75" transform="rotate(-25 20 17)"/></svg>`;
65	const COIN = `<svg class="icon" viewBox="0 0 64 64"><defs><radialGradient id="cg" cx="35%" cy="30%" r="80%"><stop offset="0" stop-color="#fff3b0"/><stop offset="0.5" stop-color="#ffc21f"/><stop offset="1" stop-color="#d98200"/></radialGradient></defs><circle cx="32" cy="32" r="29" fill="url(#cg)" stroke="#b86a00" stroke-width="3"/><circle cx="32" cy="32" r="22" fill="none" stroke="#ffe27a" stroke-width="2.5"/><text x="32" y="44" text-anchor="middle" font-family="Baloo 2, sans-serif" font-weight="800" font-size="34" fill="#c46f00">$</text></svg>`;
66	const MEDAL = `<svg viewBox="0 0 64 64" width="100%" height="100%"><defs><radialGradient id="mg" cx="35%" cy="30%" r="80%"><stop offset="0" stop-color="#fff2b8"/><stop offset=".55" stop-color="#ffc23a"/><stop offset="1" stop-color="#c47500"/></radialGradient></defs><circle cx="32" cy="32" r="29" fill="url(#mg)" stroke="#8a4a00" stroke-width="2"/><circle cx="32" cy="32" r="21" fill="#7a3b10"/><path d="M21 33 L29 41 L44 24" fill="none" stroke="#ffe48a" stroke-width="6" stroke-linecap="round" stroke-linejoin="round"/></svg>`;
67	const LAUREL = `<svg viewBox="0 0 60 64" width="100%" height="100%"><defs><linearGradient id="lg" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="#fff0a8"/><stop offset="1" stop-color="#e09a12"/></linearGradient></defs><path d="M46 62 C22 54 10 36 14 6" fill="none" stroke="url(#lg)" stroke-width="3.5" stroke-linecap="round"/>${[0, 1, 2, 3, 4, 5]
68	  .map((i) => {
